SELECT COUNT(*) AS story_bank_rows FROM inspirations WHERE notion_page_id LIKE '331c00c90b9381eeb995cc757bfc89a4#%';
SELECT config_key, version, length(config_value) AS len FROM brand_config WHERE config_key='canonical_bio';
